  const flashEl = document.getElementById("flash");
  function flash(msg){ flashEl.textContent=msg; flashEl.classList.add("show"); setTimeout(()=>flashEl.classList.remove("show"), 4000); }

  // --- save / update flow ---
  const overlay = document.getElementById("overlay");
  const urlInput = document.getElementById("urlInput");
  const rlSwitch = document.getElementById("rlSwitch");
  document.getElementById("saveBtn").onclick = startSave;
  urlInput.addEventListener("keydown", e=>{ if(e.key==="Enter") startSave(); });
  rlSwitch.onclick = ()=>{ readLater=!readLater; rlSwitch.classList.toggle("on", readLater); };

  function setSwitch(v){ readLater=v; rlSwitch.classList.toggle("on", v); }

  function renderSuggest(){
    const box=document.getElementById("suggest");
    const current=document.getElementById("fTags").value.split(",").map(s=>s.trim().toLowerCase()).filter(Boolean);
    const opts=knownTags().filter(t=>!current.includes(t.toLowerCase()));
    box.innerHTML = opts.length? `<span class="s-label">Labels you've used:</span>`+opts.map(t=>`<span class="chip" data-t="${esc(t)}">${esc(t)}</span>`).join("") : "";
    box.querySelectorAll(".chip").forEach(c=> c.onclick=()=>{
      const f=document.getElementById("fTags");
      const arr=f.value.split(",").map(s=>s.trim()).filter(Boolean); arr.push(c.dataset.t);
      f.value=arr.join(", "); renderSuggest();
    });
  }
  document.getElementById("fTags").addEventListener("input", renderSuggest);

  function startSave(){
    const url = urlInput.value.trim();
    if(!url) return;
    const key = normUrl(url);
    const existing = bookmarks.find(b=>normUrl(b.url)===key);
    if(existing){ openEdit(existing); return; }

    editingId = null;
    pending = { url, domain: domainOf(url), preview:null };
    document.getElementById("urlField").style.display = "none";
    document.getElementById("modalTitle").textContent = "Save this link";
    document.getElementById("modalHint").textContent = "Reading the page…";
    document.getElementById("fTitle").value = "…";
    document.getElementById("fDesc").value = "";
    document.getElementById("fNote").value = "";
    document.getElementById("fTags").value = "";
    setSwitch(true);
    document.getElementById("confirmBtn").textContent = "Save to my list";
    paintPreview(null, pending.domain, "reading the page…");
    document.getElementById("titleAuto").style.display="none";
    document.getElementById("descAuto").style.display="none";
    renderSuggest();
    overlay.classList.add("open");
    setTimeout(()=>{
      const d = fetchDetails(url);
      pending.preview = d.preview; pending.domain=d.domain;
      document.getElementById("fTitle").value = d.title;
      document.getElementById("fDesc").value = d.desc;
      document.getElementById("modalHint").textContent = "We filled in the details from the page. Adjust anything you like.";
      document.getElementById("titleAuto").style.display = d.auto? "block":"none";
      document.getElementById("descAuto").style.display = d.desc? "block":"none";
      paintPreview(d.preview, d.domain, d.preview? "preview image + site icon collected" : "site icon collected (no preview image on this page)");
    }, 650);
  }

  function openEdit(b){
    editingId = b.id;
    pending = { url:b.url, domain:b.domain, preview:b.preview };
    document.getElementById("modalTitle").textContent = "You already saved this";
    document.getElementById("modalHint").textContent = "Here's the one you saved before — update anything you like.";
    document.getElementById("urlField").style.display = "block";
    document.getElementById("fUrl").value = b.url;
    document.getElementById("fTitle").value = b.title;
    document.getElementById("fDesc").value = b.desc||"";
    document.getElementById("fNote").value = b.note||"";
    document.getElementById("fTags").value = (b.tags||[]).join(", ");
    setSwitch(!!b.readLater);
    document.getElementById("confirmBtn").textContent = "Update";
    document.getElementById("titleAuto").style.display="none";
    document.getElementById("descAuto").style.display="none";
    paintPreview(b.preview, b.domain, "already in your list");
    renderSuggest();
    overlay.classList.add("open");
  }

  function paintPreview(preview, domain, cap){
    const col=colorFor(domain||"x");
    const t=document.getElementById("mThumb");
    if(preview){ t.style.display="flex"; t.style.background=`linear-gradient(135deg,${col},${col})`; t.style.color="#fff"; t.textContent=preview; }
    else { t.style.display="none"; }
    const f=document.getElementById("mFav"); f.style.background=col; f.textContent=monogram(domain);
    document.getElementById("previewCap").textContent=cap;
  }

  document.getElementById("cancelBtn").onclick = ()=> overlay.classList.remove("open");
  document.getElementById("confirmBtn").onclick = ()=>{
    const tags = document.getElementById("fTags").value.split(",").map(s=>s.trim()).filter(Boolean);
    const finalUrl = editingId ? (document.getElementById("fUrl").value.trim() || pending.url) : pending.url;
    const data = {
      url: finalUrl,
      domain: domainOf(finalUrl),
      preview: pending.preview,
      title: document.getElementById("fTitle").value.trim() || pending.url,
      desc: document.getElementById("fDesc").value.trim(),
      note: document.getElementById("fNote").value.trim(),
      tags: tags,
      readLater: readLater
    };
    if(editingId){
      const i=bookmarks.findIndex(b=>b.id===editingId);
      if(i>=0) bookmarks[i]={...bookmarks[i], ...data};
      save(); render(); overlay.classList.remove("open");
      flash("Updated your saved link.");
      highlight(editingId);
    } else {
      data.id = Date.now();
      bookmarks.unshift(data);
      save(); render(); overlay.classList.remove("open");
      urlInput.value="";
    }
  };
  function highlight(id){ const el=document.getElementById("item-"+id); if(el){ el.scrollIntoView({behavior:"smooth",block:"center"}); el.classList.add("flash-hit"); setTimeout(()=>el.classList.remove("flash-hit"),1600); } }

  render();
  document.body.setAttribute("data-harness-ready","true");
</script>
